previewCss:
.darma-loader-helicopter {
  position: relative;
  width: 52px;
  height: 40px;
  animation: darma-loader-helicopter-hover 1.4s ease-in-out infinite;
}
.darma-loader-helicopter::before {
  content: "";
  position: absolute;
  bottom: 8px;
  left: 6px;
  width: 30px;
  height: 16px;
  background: var(--loader-color, #6366f1);
  border-radius: 12px 8px 8px 12px;
}
.darma-loader-helicopter::after {
  content: "";
  position: absolute;
  top: 16px;
  left: 34px;
  width: 16px;
  height: 4px;
  background: var(--loader-color, #6366f1);
  border-radius: 2px;
}
.darma-loader-helicopter i {
  position: absolute;
  top: 8px;
  left: 19px;
  width: 4px;
  height: 10px;
  background: #4338ca;
}
.darma-loader-helicopter i::before {
  content: "";
  position: absolute;
  top: -3px;
  left: 50%;
  width: 44px;
  height: 3px;
  margin-left: -22px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  transform-origin: center;
  animation: darma-loader-helicopter-spin 0.18s linear infinite;
}
@keyframes darma-loader-helicopter-hover {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}
@keyframes darma-loader-helicopter-spin { to { transform: rotate(360deg); } }

